  OwnerAction(g);BarFront(g);var employee=State.server;var active=State.guests.FirstOrDefault(c=>c.id==employee.job);if(active!=null&&active.stage==3&&employee.batch.Count>1){int target=Math.Min(employee.batch.Count-1,(int)(employee.progress/(10+State.layout*2)));active=State.guests.FirstOrDefault(c=>c.id==employee.batch[target])??active;}PointF server=active!=null&&active.stage!=2?HallNavigation.Approaches[active.table]:HallNavigation.CounterFor(State.layout);var serverPose=Pose("server",server,true);var actors=new List<KeyValuePair<float,Action>>();
