  if(KitchenArt!=null){g.DrawImage(KitchenArt,new Rectangle(955,40,405,245));using(var pen=new Pen(GuildChrome.Gold,3))g.DrawRectangle(pen,955,40,405,245);}PointF chef=new PointF(1130,235);if(State.chef.action=="拿取食材")chef=Blend(new PointF(1205,235),chef,Math.Min(1,State.chef.progress/2));Walker(g,"lyse",Clerk,chef,102,State.chef.action,"chef",true);chef=Pose("chef",chef,true).position;DrawTag(g,"厨房 · "+State.chef.action,new PointF(1155,180));g.ResetTransform();}
