  refresh=()=>{if(s.wordQuestion==null)s.wordQuestion=ExpeditionVocabulary.Next(save.rogue,VocabularyBank(mode),DateTime.Today);var q=s.wordQuestion;bool feedback=s.guidanceFeedback!=null,available=q.kind>=0,spelling=q.kind==3;progress.Content=VocabularyProgressText(mode);title.Text=feedback?"指导结算":"英语指导 · "+(s.guidanceCount%3+1)+" / 3";status.Text=feedback?s.guidanceFeedback:available?ExpeditionVocabulary.Status(save.rogue,q,DateTime.Today):"今日暂无待学词汇，可返回英语指导选择词库或继续营业。";status.ForeColor=feedback?(s.guidanceFeedback.StartsWith("回答正确")?Color.FromArgb(112,225,155):Color.FromArgb(249,151,126)):GuildChrome.Ivory;word.Text=!available?"":feedback||q.kind==0?q.entry.word:ExpeditionVocabulary.Meaning(q.entry);word.Font=feedback||q.kind==0?GameTheme.Latin(feedback?16:21):GameTheme.Body(15);word.Visible=available;hear.Visible=available&&(feedback||q.kind==0);star.Visible=available;star.Selected=available&&save.words.Any(v=>v.text.Equals(q.entry.word,StringComparison.OrdinalIgnoreCase));meaning.Visible=feedback&&available;meaning.Content=meaning.Visible?ExpeditionVocabulary.Meaning(q.entry):"";input.Visible=spelling&&!feedback;for(int i=0;i<4;i++){buttons[i].Visible=available&&!spelling&&!feedback;buttons[i].Text=i<q.options.Count?((char)('A'+i))+". "+q.options[i]:"";}next.Visible=feedback||spelling||!available;next.Text=feedback?"继续 · Enter":spelling?"提交拼写":"刷新到期复习";if(!feedback&&spelling)input.Text=q.spellingDraft??"";layout();if(feedback)next.Focus();};input.TextChanged+=(o,e)=>{if(s.wordQuestion!=null)s.wordQuestion.spellingDraft=input.Text;};input.KeyDown+=(o,e)=>{if(e.KeyCode==Keys.Enter){e.Handled=e.SuppressKeyPress=true;next.PerformClick();}};parent.Resize+=(o,e)=>{if(!word.IsDisposed)layout();};hallSaveStudy=()=>{};refresh();}
 void BuildHallManagement(Panel parent,TavernHallState s,Func<bool> paused,Action<bool> pause){hallRefreshAudio=null;hallSaveStudy=null;int tab=Math.Max(0,hallManagementTab);Action render=null;render=()=>{while(parent.Controls.Count>0)parent.Controls[0].Dispose();var rows=HallRows(parent,7);rows.RowStyles[0].Height=40;for(int i=1;i<7;i++)rows.RowStyles[i].Height=10;var text=new HallPagedText{Dock=DockStyle.Fill};rows.Controls.Add(text,0,0);HallButton(rows,6,"切换：员工 → 菜单 → 设施 / 事件",()=>{tab=(tab+1)%3;render();});if(tab==0){var c=s.chef;var w=s.server;text.Content=EmployeeText(c,true)+"\n\n"+EmployeeText(w,false)+"\n熟客满意接待 "+s.regularVisits+" 次 · "+(s.regularVisits>=3?"熟客开始回访":"3次满意接待后回访");HallButton(rows,1,"查看实时能力与成长",render);HallButton(rows,2,"库存补购："+(s.autoBuy?"开启":"关闭"),()=>{s.autoBuy=!s.autoBuy;render();});HallButton(rows,3,"每日补购上限 "+s.purchaseLimit+" 金币",()=>{s.purchaseLimit=s.purchaseLimit==80?120:s.purchaseLimit==120?0:80;render();});HallButton(rows,4,"休息：疲劳达到体力上限自动休息",()=>{s.notice="厨师和服务员会自行休息，空闲时也恢复体力。";});HallButton(rows,5,"分工：莉瑟厨房 · 艾莉娅大厅 / 饮品",()=>s.notice="陆川负责安排与指导；三级解锁双份切配 / 双盘送餐，五级解锁拿手料理 / 熟练服务。" );}
 else if(tab==1){text.Content="今日菜单 · 制作成长：初学 → 熟练（8份）→ 招牌（24份）\n胡萝卜 "+s.carrots+" · 面粉 "+s.flour+"\n收入 "+s.revenue+" − 采购 "+s.cost+" = 净收益 "+(s.revenue-s.cost)+"\n两种原料每单位2金币；不同菜品耗料、价格与耗时不同。";for(int i=0;i<4;i++){int dish=i;HallButton(rows,i+1,TavernHall.Dishes[i]+" · "+TavernHall.Prices[i]+"金币 · "+new[]{"初学","熟练","招牌"}[s.recipes[i].Rank]+" "+s.recipes[i].made+"份 · "+(s.recipes[i].enabled?"上架":"停售"),()=>{if(s.recipes.Count(r=>r.enabled)==1&&s.recipes[dish].enabled){s.notice="至少保留一道菜单。";return;}s.recipes[dish].enabled=!s.recipes[dish].enabled;render();});}HallButton(rows,5,"采购各8份食材 · 32金币",()=>{if(save.rogue.coins<32){s.notice="金币不足，开启自动补购可少量补充。";return;}save.rogue.coins-=32;s.cost+=32;s.carrots+=8;s.flour+=8;Persist();render();});}
 else{text.Content="出餐台改善交接速度；双锅炉灶让三级厨师同时制作两份。\n布局编辑时暂停营业，固定入口与通路保留。\n当前布局："+(s.layout==0?"吧台左侧交接":"吧台右侧交接，搬运路线较长")+"\n"+(s.eventPending?"团体订餐：接下来接待3人，额外奖励18金币；没有限时，题组结束后处理。":"第2日起开放团体订餐。")+"\n"+s.notice;HallButton(rows,1,"改善出餐台 · 30金币（"+s.upgrade+" / 2）",()=>{if(s.upgrade>=2){s.notice="出餐台已升至满级。";return;}if(save.rogue.coins<30){s.notice="改善出餐台需要30金币。";return;}if(s.upgrade<2&&save.rogue.coins>=30){save.rogue.coins-=30;s.upgrade++;Persist();render();}});HallButton(rows,2,"双锅炉灶 · 45金币"+(s.stove>0?" · 已安装":""),()=>{if(s.stove>0){s.notice="双锅炉灶已经安装。";return;}if(save.rogue.coins<45){s.notice="安装双锅炉灶需要45金币。";return;}if(s.stove==0&&save.rogue.coins>=45){save.rogue.coins-=45;s.stove=1;Persist();render();}});HallButton(rows,3,"布局：暂停并调整出餐路线",()=>{pause(true);s.layout=1-s.layout;s.notice="已切换合法交接位置，入口与通路畅通；点击继续恢复营业。";render();});HallButton(rows,4,"接受团体订餐",()=>{if(s.study!=null&&!s.study.finished){s.notice="事件保留，完整题组结束后再决定。";return;}if(s.eventPending){s.eventPending=false;s.eventAccepted=true;s.notice="已接受：完成接下来3次接待，无额外限时。";render();}});HallButton(rows,5,"暂不接单 / 查看结算",()=>{if(s.eventPending&&s.study!=null&&!s.study.finished){s.notice="事件保留，完整题组结束后再决定。";return;}if(s.eventPending){s.eventPending=false;s.eventResolved=true;}s.notice="营业收入 "+s.revenue+"，采购成本 "+s.cost+"，净收益 "+(s.revenue-s.cost)+"；目标6人："+(s.served>=6?"已达成":"继续努力");render();});} DateTime refreshed=DateTime.MinValue;hallRefreshManagement=()=>{if(text.IsDisposed||(DateTime.UtcNow-refreshed).TotalSeconds<1)return;refreshed=DateTime.UtcNow;if(tab==0)text.LiveContent=EmployeeText(s.chef,true)+"\n\n"+EmployeeText(s.server,false)+"\n熟客满意接待 "+s.regularVisits+" 次 · "+(s.regularVisits>=3?"熟客开始回访":"3次满意接待后回访");else if(tab==1){text.LiveContent="今日菜单 · 制作成长：初学 → 熟练（8份）→ 招牌（24份）\n胡萝卜 "+s.carrots+" · 面粉 "+s.flour+"\n收入 "+s.revenue+" − 采购 "+s.cost+" = 净收益 "+(s.revenue-s.cost)+"\n两种原料每单位2金币；不同菜品耗料、价格与耗时不同。";for(int dish=0;dish<4;dish++){var button=rows.GetControlFromPosition(0,dish+1) as VNButton;if(button!=null)button.Text=TavernHall.Dishes[dish]+" · "+TavernHall.Prices[dish]+"金币 · "+new[]{"初学","熟练","招牌"}[s.recipes[dish].Rank]+" "+s.recipes[dish].made+"份 · "+(s.recipes[dish].enabled?"上架":"停售");}}}; };render();}
 string EmployeeText(HallEmployee e,bool chef){return e.name+" · "+(chef?"厨师 · 特长：细心":"服务员 · 特长：健谈")+" Lv."+e.level+"\n手艺 "+e.Craft+" · 效率 "+e.Efficiency+" · 服务 "+e.Service+" · 体力 "+e.Stamina+"\n成长 "+e.xp+" / "+(e.level==5?"满级":e.NextXp.ToString())+" · 工作贡献 "+e.workXp+" / 研修贡献 "+e.listeningXp+"\n疲劳 "+(int)e.fatigue+" · "+e.action+"\n三级："+(chef?"双份切配（需双锅）":"双盘送餐")+" · 五级："+(chef?"拿手料理（品质+3）":"熟练服务（小费提升）");}
